create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,created_at,updated_at) values
 ('91000000-0000-4000-8000-000000000001','response-subject@example.invalid',now(),now()),
 ('91000000-0000-4000-8000-000000000002','response-moderator@example.invalid',now(),now()),
 ('91000000-0000-4000-8000-000000000003','response-founding-admin@example.invalid',now(),now());
insert into private.moderation_admins(user_id) values('91000000-0000-4000-8000-000000000002');
insert into private.founding_driver_admins(user_id) values('91000000-0000-4000-8000-000000000003');
insert into freightiq_response_proof.cases(id,subject_id,surface) values
 ('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','library'),
 ('92000000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000001','operations');
select ok(not has_table_privilege('authenticated','freightiq_response_proof.cases','select'),'case table is not client-readable');
select ok(not has_table_privilege('service_role','freightiq_response_proof.audit','insert'),'no direct service-role audit mutation');
select ok(not has_function_privilege('anon','freightiq_response_proof.act(uuid,integer,integer,text)','execute'),'anonymous action denied');
select ok(not has_function_privilege('authenticated','freightiq_response_proof.remaining_pause(text)','execute'),'internal pause lookup private');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where pronamespace='freightiq_response_proof'::regnamespace),'all privileged helpers use fixed search path');
set local role authenticated;
set local "request.method"='POST';
set local "request.headers"='{}';
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000001';
select throws_ok($$select freightiq_response_proof.get_case('92000000-0000-4000-8000-000000000001')$$,'42501','Moderator access required.','ordinary driver cannot inspect case');
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,900,'suspicious_collection')$$,'42501','Moderator access required.','ordinary driver cannot pause');
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000003';
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,900,'suspicious_collection')$$,'42501','Moderator access required.','Founding Driver admin is not moderator');
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000002';
select ok(not (freightiq_response_proof.get_case('92000000-0000-4000-8000-000000000001') ? 'subject_id'),'moderator reply omits raw subject ID');
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,86401,'suspicious_collection')$$,'22023','Invalid action.','unapproved duration refused');
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,900,'raw private notes')$$,'22023','Invalid action.','free-text reason cannot retain sensitive content');
set local "request.method"='GET';
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,900,'suspicious_collection')$$,'PT405','POST required.','GET cannot mutate');
set local "request.method"='POST';
set local "request.headers"='{"prefer":"tx=rollback"}';
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,900,'suspicious_collection')$$,'22023','Invalid action.','rollback preference refused');
set local "request.headers"='{}';
select is(freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,900,'suspicious_collection')->>'version','1','15 minute pause saved');
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',0,0,'mistake')$$,'PT409','Case changed. Reload before acting.','stale restore cannot overwrite newer decision');
select is(freightiq_response_proof.act('92000000-0000-4000-8000-000000000002',0,3600,'suspicious_collection')->>'version','1','one hour Operations pause saved');
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000001';
select is(freightiq_response_proof.read_library('search_stops','{"p_search_text":"fictional"}')->>'code','FREIGHTIQ_READ_THROTTLED','library proof wrapper refuses paused reads');
select is(freightiq_response_proof.read_library('search_stops','{}')->'data','null'::jsonb,'paused library discloses no data');
select is(freightiq_response_proof.read_operations()->>'code','OPERATIONS_READ_THROTTLED','Operations proof wrapper refuses paused reads');
select is(current_setting('response.status'),'429','pause uses compatible refusal status');
select is(public.create_freightiq_stop_v1('response-proof-stop','Response Proof',null,39,-108),'response-proof-stop','actual stop creation works during both pauses');
select ok(public.save_freightiq_report_v1('response-proof-stop') is not null,'actual Intel save works during both pauses');
select ok(public.set_owned_freightiq_delivery_zone_v1('response-proof-stop',39.01,-108.01),'actual DZ save works during pauses');
select is(public.get_owned_freightiq_stop_editor_v1('response-proof-stop')->>'id','response-proof-stop','owned editor loads during pauses');
reset role;
select is((select count(*) from private.contributor_restrictions where user_id='91000000-0000-4000-8000-000000000001'),0::bigint,'no contribution restriction created');
select is((select count(*) from freightiq_response_proof.audit),2::bigint,'only successful actions audited');
select is((select count(*) from freightiq_response_proof.audit where moderator_id='91000000-0000-4000-8000-000000000002'),2::bigint,'audit records actual moderator');
set local role authenticated;
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000002';
select is(freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',1,0,'review_complete')->>'version','2','restore saved with audit version');
reset role;
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000001';
select is(freightiq_response_proof.remaining_pause('library'),0,'restored library immediately has no pause');
select ok(freightiq_response_proof.remaining_pause('operations')>0,'library restore does not remove Operations pause');
update freightiq_response_proof.cases set paused_until=clock_timestamp()-interval '1 second' where surface='operations';
select is(freightiq_response_proof.remaining_pause('operations'),0,'pause expires without scheduler');
set local role authenticated;
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000002';
select is(freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',2,86400,'suspicious_collection')->>'version','3','24 hour maximum accepted');
reset role;
select ok((select paused_until<=clock_timestamp()+interval '24 hours' from freightiq_response_proof.cases where surface='library'),'24 hour pause bounded by server time');
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000003';
select is(freightiq_response_proof.remaining_pause('library'),0,'pause does not affect another account');
create function freightiq_response_proof.break_audit() returns trigger language plpgsql as $$
begin raise exception 'Simulated audit failure'; end; $$;
create trigger break_audit before insert on freightiq_response_proof.audit
  for each row execute function freightiq_response_proof.break_audit();
set local role authenticated;
set local "request.jwt.claim.sub"='91000000-0000-4000-8000-000000000002';
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',3,0,'mistake')$$,'P0001','Simulated audit failure','audit failure refuses the action');
reset role;
select is((select version from freightiq_response_proof.cases where surface='library'),3,'failed audit cannot leave unaudited state change');
select ok((select paused_until>clock_timestamp() from freightiq_response_proof.cases where surface='library'),'failed restore retains prior pause');
drop trigger break_audit on freightiq_response_proof.audit;
update freightiq_response_proof.cases set created_at=now()-interval '31 days',expires_at=now()-interval '1 day' where surface='operations';
set local role authenticated;
select ok(freightiq_response_proof.get_case('92000000-0000-4000-8000-000000000002') is null,'expired case hidden without waiting for cleanup');
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000002',1,900,'suspicious_collection')$$,'PT404','Case unavailable.','expired case cannot be reactivated');
reset role;
select freightiq_response_proof.purge_expired();
select is((select count(*) from freightiq_response_proof.cases where surface='operations'),0::bigint,'expired case is purged');
select is((select count(*) from freightiq_response_proof.audit where case_id='92000000-0000-4000-8000-000000000002'),0::bigint,'purge removes related audit records');
delete from private.moderation_admins where user_id='91000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select freightiq_response_proof.act('92000000-0000-4000-8000-000000000001',3,0,'mistake')$$,'42501','Moderator access required.','revoked moderator cannot restore with old identity');
reset role;
delete from auth.users where id='91000000-0000-4000-8000-000000000001';
select is((select count(*) from freightiq_response_proof.cases),0::bigint,'account deletion removes cases');
select is((select count(*) from freightiq_response_proof.audit),0::bigint,'account deletion cascades action records');
select * from finish();
